package io.github.hienpham0344.stayfinder.media;
import io.github.hienpham0344.stayfinder.media.service.*;import io.github.hienpham0344.stayfinder.media.entity.MediaAsset;import io.github.hienpham0344.stayfinder.media.repository.MediaAssetRepository;
import io.github.hienpham0344.stayfinder.common.exception.BusinessException;import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.mock.web.MockMultipartFile;
import java.nio.file.Path;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class MediaOwnershipTest{
 @TempDir Path root;MediaAssetRepository rows;LocalMediaStorage storage;MediaService service;UUID owner,other,review;Clock clock;
 @BeforeEach void setup(){owner=UUID.randomUUID();other=UUID.randomUUID();review=UUID.randomUUID();clock=Clock.fixed(Instant.parse("2026-10-13T12:00:00Z"),ZoneOffset.UTC);rows=mock(MediaAssetRepository.class);storage=new LocalMediaStorage(root);service=new MediaService(rows,storage,new MediaUrlSigner("synthetic-media-key-01234567890123456789",clock),mock(EntityManager.class),clock);}
 MediaAsset asset(UUID user){var a=new MediaAsset();a.setId(UUID.randomUUID());a.setUserId(user);a.setCreatedAt(clock.instant());a.setUnattachedSince(clock.instant());a.setMimeType("image/png");a.setSizeBytes(MediaFileValidationTest.png().length);return a;}
 @Test void cannotAttachAnotherOwnersOrAnotherReviewsAsset(){var a=asset(other);when(rows.lockById(a.getId())).thenReturn(Optional.of(a));when(rows.findByReviewId(review)).thenReturn(List.of());assertThrows(BusinessException.class,()->service.replaceAttachments(owner,review,List.of(a.getId())));a.setUserId(owner);a.setReviewId(UUID.randomUUID());assertThrows(BusinessException.class,()->service.replaceAttachments(owner,review,List.of(a.getId())));assertNotEquals(review,a.getReviewId());}
 @Test void attachmentLimitDuplicatesAndUnattachedDeleteAreEnforced(){assertThrows(BusinessException.class,()->service.replaceAttachments(owner,review,java.util.stream.IntStream.range(0,6).mapToObj(i->UUID.randomUUID()).toList()));var a=asset(owner);assertThrows(BusinessException.class,()->service.replaceAttachments(owner,review,List.of(a.getId(),a.getId())));a.setReviewId(review);when(rows.lockById(a.getId())).thenReturn(Optional.of(a));assertThrows(BusinessException.class,()->service.deleteUnattached(owner,a.getId()));verify(rows,never()).delete(any());}
 @Test void failedDatabaseUploadRemovesGeneratedFile(){when(rows.saveAndFlush(any())).thenThrow(new IllegalStateException("Synthetic persistence failure"));assertThrows(IllegalStateException.class,()->service.upload(owner,new MockMultipartFile("image","valid.png","image/png",MediaFileValidationTest.png())));try(var files=java.nio.file.Files.list(root)){assertEquals(0,files.count());}catch(java.io.IOException e){throw new AssertionError(e);}}
 @Test void signedReadBindsExistingAssetAndExpiration(){var a=asset(owner);a.setReviewId(review);storage.store(a.getId(),new MockMultipartFile("image","valid.png","image/png",MediaFileValidationTest.png()));when(rows.findById(a.getId())).thenReturn(Optional.of(a));var signer=new MediaUrlSigner("synthetic-media-key-01234567890123456789",clock);var t=signer.ticket(a.getId());assertArrayEquals(MediaFileValidationTest.png(),service.openSigned(a.getId(),t.expiresAt(),t.signature()).bytes());assertThrows(BusinessException.class,()->service.openSigned(a.getId(),t.expiresAt(),"00"));}
}
